"""Synthetic judge set: pairs of hand-made forks with a known better one. No workers, only the referee.
Each case: task, fork A diff text, fork B diff text, which is better ('A'/'B'/'tie'), why, and a tag."""
BASE_REMOVE = "    def remove(self, sku: str) -> None:\n        del self.lines[sku]\n"
